  input [7:0] in_data,
  output in_ready,
  output out_valid,
  output [7:0] out_data,
  input out_ready
);
  reg full;
  reg [7:0] data;
  assign in_ready = ~full | out_ready;
  assign out_valid = full;
  assign out_data = data;
  wire accept = in_valid & in_ready;
  wire consume = out_valid & out_ready;
  always @(posedge clk) begin
    if (rst) begin
      full <= 1'b0;
      data <= 8'h00;
    end else begin
      if (accept) begin
        data <= in_data;
        full <= 1'b1;
      end else if (consume) begin
        full <= 1'b0;
      end
    end
  end
endmodule
